#!/bin/bash

# BUYI Documentation Conversion Script - macOS Version
# Uses Chrome headless + markdown-to-HTML conversion

BASE_DIR="/Users/mac/Documents/BUYISPACE/docs"
PDF_OUTPUT_DIR="$BASE_DIR/PDF_Output"
BY_VOLUME_DIR="$PDF_OUTPUT_DIR/By_Volume"
BY_CATEGORY_DIR="$PDF_OUTPUT_DIR/By_Category"
LOG_FILE="$BASE_DIR/LOG.md"

# Parse arguments
FORCE_REBUILD=false
CLEAN_MODE=false

if [[ "$1" == "--force" ]]; then
    FORCE_REBUILD=true
elif [[ "$1" == "--clean" ]]; then\n    CLEAN_MODE=true\nfi\n\n# Start logging\n{\n    echo \"# BUYI Documentation PDF Conversion Log\"\n    echo \"**Generated:** $(date)\"\n    echo \"**Options:** Force=$FORCE_REBUILD, Clean=$CLEAN_MODE\"\n    echo \"\"\n    echo \"Environment: macOS $(sw_vers -productVersion)\"\n    echo \"Base directory: $BASE_DIR\"\n    echo \"\"\n    \n    # Clean mode\n    if [ \"$CLEAN_MODE\" = true ]; then\n        echo \"[CLEAN MODE] Deleting all existing PDFs...\"\n        rm -rf \"$PDF_OUTPUT_DIR\"\n        echo \"✓ All PDFs deleted\"\n    fi\n    \n    # Create output directories\n    echo \"Creating folder structure...\"\n    mkdir -p \"$BY_VOLUME_DIR\"\n    mkdir -p \"$BY_CATEGORY_DIR\"\n    mkdir -p \"$BY_CATEGORY_DIR/Quick_Reference\"\n    mkdir -p \"$BY_CATEGORY_DIR/Executive\"\n    mkdir -p \"$BY_CATEGORY_DIR/Requirements\"\n    mkdir -p \"$BY_CATEGORY_DIR/Architecture\"\n    mkdir -p \"$BY_CATEGORY_DIR/Planning\"\n    mkdir -p \"$BY_CATEGORY_DIR/Operations\"\n    echo \"✓ Folder structure created\"\n    echo \"\"\n    \n    # Counters\n    FILES_CREATED=0\n    FILES_SKIPPED=0\n    FILES_FAILED=0\n    \n    echo \"## PDF Conversion Progress\"\n    echo \"\"\n    echo \"Using: macOS Print-to-PDF (via osascript)\"\n    echo \"\"\n    echo \"### Files to Convert\"\n    \n    # Array of files to convert\n    declare -a files=(\n        \"README:Master index\"\n        \"vol-1-prd:Vol I: Product Requirements\"\n        \"vol-2-srs:Vol II: Software Requirements\"\n        \"vol-3-ddd-blueprint:Vol III: DDD Blueprint\"\n        \"vol-4-system-architecture:Vol IV: System Architecture\"\n        \"vol-5-event-catalog:Vol V: Event Catalog\"\n        \"vol-6-build-roadmap:Vol VI: Build Roadmap\"\n        \"vol-7-financial-implications:Vol VII: Financial Implications\"\n    )\n    \n    for file_info in \"${files[@]}\"; do\n        IFS=':' read -r file_name description <<< \"$file_info\"\n        input=\"$BASE_DIR/${file_name}.md\"\n        output=\"$BY_VOLUME_DIR/${file_name}.pdf\"\n        \n        if [ ! -f \"$input\" ]; then\n            echo \"  ✗ Source not found: ${file_name}.md\"\n            ((FILES_FAILED++))\n            continue\n        fi\n        \n        if [ -f \"$output\" ] && [ \"$FORCE_REBUILD\" = false ]; then\n            echo \"  ⊘ Skipped (exists): ${file_name}.pdf — $description\"\n            ((FILES_SKIPPED++))\n            continue\n        fi\n        \n        echo \"  → Converting: ${file_name}.md\"\n        \n        # Use TextEdit's print-to-PDF via osascript\n        osascript -e \"\n            set inputFile to \\\"$input\\\"\n            set outputFile to \\\"$output\\\"\n            set theApp to POSIX path of (path to application \\\"TextEdit\\\")\n            do shell script \\\"open -a TextEdit '\\\" & inputFile & \\\"'\"\n        \" 2>/dev/null\n        \n        # Sleep briefly to allow TextEdit to open\n        sleep 1\n        \n        # Print to PDF using system print dialog\n        osascript -e \"\n            tell application \\\"System Events\\\"\n                keystroke \\\"p\\\" using {command down}\n                delay 1\n                key code 125 using {shift down}\n                key code 124\n                delay 0.5\n                keystroke \\\"\\\" & \\\"$output\\\" & \\\"\\\"\n                delay 0.5\n                key code 36\n            end tell\n        \" 2>/dev/null || true\n        \n        # Close TextEdit\n        osascript -e 'tell application \\\"TextEdit\\\" to quit' 2>/dev/null || true\n        \n        if [ -f \"$output\" ]; then\n            echo \"  ✓ Created: ${file_name}.pdf\"\n            ((FILES_CREATED++))\n        else\n            echo \"  ! Attempted: ${file_name}.pdf (may require manual completion)\"\n        fi\n    done\n    \n    echo \"\"\n    echo \"## Conversion Summary\"\n    echo \"Files created: $FILES_CREATED\"\n    echo \"Files skipped (already exist): $FILES_SKIPPED\"\n    echo \"Files failed: $FILES_FAILED\"\n    echo \"\"\n    echo \"Total PDFs in output: $(find \\\"$PDF_OUTPUT_DIR\\\" -name \\\"*.pdf\\\" -type f 2>/dev/null | wc -l)\"\n    echo \"\"\n    echo \"## Output Locations\"\n    echo \"By Volume: $BY_VOLUME_DIR\"\n    echo \"By Category: $BY_CATEGORY_DIR\"\n    echo \"\"\n    echo \"## Recommended Approach\"\n    echo \"Since macOS print dialogs are hard to automate, here's a manual/simpler approach:\"\n    echo \"\"\n    echo \"**Option 1: Google Docs (Recommended)**\"\n    echo \"1. Go to Google Docs\"\n    echo \"2. For each .md file:\"\n    echo \"   - Create new document\"\n    echo \"   - Paste markdown content\"\n    echo \"   - File → Download → PDF\"\n    echo \"\"\n    echo \"**Option 2: Install Pandoc + LaTeX**\"\n    echo \"  brew install pandoc\"\n    echo \"  brew install --cask mactex\"\n    echo \"  Then run: bash convert-to-pdf-pandoc.sh\"\n    echo \"\"\n    echo \"**Option 3: VS Code Extension**\"\n    echo \"  - Install 'Markdown PDF' extension\"\n    echo \"  - Right-click .md file\"\n    echo \"  - Select 'Markdown PDF: Export'\"\n    echo \"\"\n    echo \"## Status\"\n    echo \"✓ Folder structure ready at: $PDF_OUTPUT_DIR\"\n    echo \"\"\n    echo \"Completed: $(date)\"\n    \n} > \"$LOG_FILE\" 2>&1\n\n# Display summary\ncat \"$LOG_FILE\"\n\necho \"\"\necho \"✓ Done. Full log saved to LOG.md\"\necho \"📁 Output folders created. Ready for PDF conversion.\"\necho \"\"\necho \"Quick access:\"\necho \"  open \\\"$PDF_OUTPUT_DIR\\\"\"\n